        collectedB.some((envelope) =>
          envelope.kind === "agui.event" &&
          (envelope.payload as { type?: string; delta?: string }).type === "TEXT_MESSAGE_CONTENT" &&
          (envelope.payload as { type?: string; delta?: string }).delta === "dedupe from pi",
