    assert.equal(
      notifications[0]?.absolutePath,
      await realpath(path.join(fixture.rootDirectory, "edit.txt")),
    );

    const ambiguous = await RunTool(fixture, "edit", {
      path: "edit.txt",
      edits: [{ oldText: "beta", newText: "delta" }],
    });
